import 'package:flutter/material.dart';

import '../../../core/theme/app_theme.dart';
import '../data/warehouse_repository.dart';

class WarehouseDashboardPage extends StatelessWidget{
  const WarehouseDashboardPage({super.key,required this.repository});final WarehouseRepository repository;
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Warehouse',style:TextStyle(fontWeight:FontWeight.w800)),Text('Central Warehouse • Live operations',style:TextStyle(fontSize:12,color:AppTheme.muted))])),body:FutureBuilder<WarehouseOverview>(future:repository.loadOverview(),builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(!s.hasData)return const Center(child:Text('Unable to load warehouse.'));final d=s.requireData;return ListView(padding:const EdgeInsets.all(24),children:[Wrap(spacing:14,runSpacing:14,children:[_Metric(label:'Receipts today',value:'${d.receiptsToday}'),_Metric(label:'Issues today',value:'${d.issuesToday}'),_Metric(label:'Transfers',value:'${d.transfersToday}',accent:AppTheme.brand),_Metric(label:'Pending putaway',value:'${d.pendingPutaway}',accent:AppTheme.warning)]),const SizedBox(height:18),LayoutBuilder(builder:(context,c)=>c.maxWidth>900?Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(flex:2,child:_Tasks(tasks:d.tasks)),const SizedBox(width:16),Expanded(child:_Utilization(items:d.utilization))]):Column(children:[_Tasks(tasks:d.tasks),const SizedBox(height:16),_Utilization(items:d.utilization)]))]);}),);
}
class _Metric extends StatelessWidget{const _Metric({required this.label,required this.value,this.accent=AppTheme.text});final String label,value;final Color accent;@override Widget build(BuildContext context)=>SizedBox(width:245,height:104,child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisAlignment:MainAxisAlignment.center,children:[Text(label,style:const TextStyle(color:AppTheme.muted,fontSize:12)),const SizedBox(height:8),Text(value,style:TextStyle(fontSize:26,fontWeight:FontWeight.w800,color:accent))]))));}
class _Tasks extends StatelessWidget{const _Tasks({required this.tasks});final List<WarehouseTask> tasks;@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Operational tasks',style:TextStyle(fontSize:17,fontWeight:FontWeight.w800)),const SizedBox(height:10),...tasks.map((t)=>ListTile(contentPadding:EdgeInsets.zero,title:Text('${t.type} • ${t.reference}',style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${t.detail}\n${t.assignee}'),isThreeLine:true,trailing:Text(t.status,style:TextStyle(color:t.status=='Pending'?AppTheme.warning:t.status=='Ready'?AppTheme.success:AppTheme.brand,fontWeight:FontWeight.w800))) ])));}
class _Utilization extends StatelessWidget{const _Utilization({required this.items});final List<WarehouseUtilization> items;@override Widget build(BuildContext context)=>Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Location utilization',style:TextStyle(fontSize:17,fontWeight:FontWeight.w800)),const SizedBox(height:16),...items.map((i)=>Padding(padding:const EdgeInsets.only(bottom:18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(i.name,style:const TextStyle(fontWeight:FontWeight.w700)),Text('${(i.percent*100).toStringAsFixed(0)}%',style:const TextStyle(color:AppTheme.muted))]),const SizedBox(height:8),LinearProgressIndicator(value:i.percent,minHeight:10,borderRadius:BorderRadius.circular(5))]))])));}
